type Environment={origin:string;local:Awaited<ReturnType<typeof syntheticRuntime>>;advance:(ms:number)=>void;ticks:()=>number;errors:string[]};
const test=base.extend<{environment:Environment}>({environment:async({},use)=>{let offset=0;const now=()=>new Date(Date.now()+offset);const admin=await testDatabase(async()=>now());const local=await syntheticRuntime(admin,await mkdtemp(path.join(tmpdir(),'trio-browser-state-')),{clock:async()=>now(),objectClock:now});const errors:string[]=[];const config={origin:'https://127.0.0.1',webRoot:path.resolve('dist/web'),https:{key:await readFile(process.env.TRIO_BROWSER_KEY!),cert:await readFile(process.env.TRIO_BROWSER_CERT!)},onBackgroundError:(code:string)=>errors.push(code)};const app=await createServer(local.runtime,config);config.origin=await app.listen({host:'127.0.0.1',port:0});let ticks=0;let ticking=false;const timer=setInterval(()=>{if(ticking)return;ticking=true;void local.runtime.tick().catch(()=>errors.push('WORKER_UNCONFIRMED')).finally(()=>{ticks++;ticking=false;});},100);try{await use({origin:config.origin,local,advance:ms=>{offset+=ms;},ticks:()=>ticks,errors});}finally{clearInterval(timer);await app.close();await local.runtime.idle();await local.close();await admin.close();}}});
