test.afterEach(async({environment},info)=>{if(info.status===info.expectedStatus)return;const state=await environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>({observedAt:tx.now,batches:(await tx.client.query('SELECT state,pause_reason,next_target_index FROM batches WHERE account_id=$1',[environment.local.accountId])).rows,requests:(await tx.client.query('SELECT state,captured_stage_order FROM processing_requests WHERE account_id=$1',[environment.local.accountId])).rows,work:(await tx.client.query('SELECT kind,state,due_at,lease_until FROM work_items WHERE account_id=$1',[environment.local.accountId])).rows}));await writeFile(artifact(info,`failure-${info.testId}.json`),JSON.stringify({clock:'WALL_ELAPSED_PLUS_EXPLICIT_OFFSET',providerCalls:environment.local.provider.calls.map(input=>({stage:input.stage,settingsVersion:input.settings.settingsVersion,targetLanguage:input.settings.targetLanguage})),backgroundErrors:environment.errors,...state},null,2));});
const activate=(control:Locator,touch:boolean)=>touch?control.tap():control.click();
async function typeValue(control:Locator,value:string,touch:boolean){await activate(control,touch);await control.press('ControlOrMeta+A');await control.pressSequentially(value);await control.press('Tab');await expect(control).toHaveValue(value);}
async function signInAndCreate(page:Page,environment:Environment,touch:boolean){
  await page.goto(environment.origin);await expect(page).toHaveTitle('Trio · 만화 번역 작업실');await expect(page.getByRole('heading',{name:'작업실에 로그인'})).toBeVisible();
  await typeValue(page.getByRole('textbox',{name:'이메일',exact:true}),'local@example.invalid',touch);await activate(page.getByRole('button',{name:'확인 코드 받기'}),touch);await typeValue(page.getByRole('textbox',{name:'이메일 확인 코드'}),'123456',touch);await activate(page.getByRole('button',{name:'코드 확인',exact:true}),touch);await expect(page.getByRole('button',{name:'새 프로젝트 만들기'})).toBeVisible();await activate(page.getByRole('button',{name:'새 프로젝트 만들기'}),touch);await expect(page.getByRole('heading',{name:'첫 페이지를 올려 주세요.'})).toBeVisible();
}
async function ownedPng(variant=0){const pixels=Buffer.alloc(400*260*4);for(let y=0;y<260;y++)for(let x=0;x<400;x++){const at=(y*400+x)*4;pixels[at]=(x+variant*23)%251;pixels[at+1]=(y+variant*41)%241;pixels[at+2]=(x+y+variant*17)%239;pixels[at+3]=x<20?128:255;}return sharp(pixels,{raw:{width:400,height:260,channels:4}}).png().toBuffer();}
async function addOwnedPages(page:Page,touch:boolean,count=1,options:{opaque?:boolean}={}){
  const images=await Promise.all(Array.from({length:count},async(_,index)=>{const bytes=await ownedPng(index);if(!options.opaque)return bytes;const opaque=await sharp(bytes).flatten({background:'#ffffff'}).png().toBuffer();const pixels=await sharp(opaque).ensureAlpha().raw().toBuffer();expect(pixels.every((value,at)=>at%4!==3||value===255),'The owned HOLD input is fully opaque before upload').toBe(true);return opaque;}));await page.getByLabel('페이지 이미지 추가',{exact:true}).setInputFiles(images.map((buffer,index)=>({name:`owned-${index+1}.png`,mimeType:'image/png',buffer})));const dialog=page.getByRole('dialog',{name:'페이지 추가 미리보기'});await expect(dialog).toBeVisible();await activate(dialog.getByRole('button',{name:`${count}개 페이지 추가`,exact:true}),touch);await expect(page.locator('.canvas-image img')).toBeVisible();return images;
}
async function settings(page:Page,environment:Environment,touch:boolean){
  const font=environment.local.runtime.options.fonts.catalog.fonts.find(item=>item.language==='ko')!.id;await page.getByLabel('원문 언어',{exact:true}).selectOption('ja');await page.getByLabel('목표 언어',{exact:true}).selectOption('ko');await page.getByLabel('모델',{exact:true}).selectOption('synthetic-v1');await page.getByLabel('처리 수준',{exact:true}).selectOption('HIGH');await page.getByLabel('기본 글꼴',{exact:true}).selectOption(font);await activate(page.getByRole('button',{name:'다음 처리 설정 저장'}),touch);await expect(page.getByRole('status').filter({hasText:'다음 처리에 사용할 설정을 저장했어요.'})).toBeVisible();return font;
}
async function currentResults(environment:Environment){return environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>(await tx.client.query<ResultRow>(`SELECT r.* FROM results r JOIN workspace_pages p ON p.account_id=r.account_id AND p.current_result_id=r.result_id JOIN workspace_contexts c ON c.account_id=p.account_id AND c.context_id=p.context_id WHERE p.account_id=$1 AND c.lifecycle='OPEN' AND NOT p.excluded ORDER BY p.display_order`,[environment.local.accountId])).rows);}
async function assertFourStages(environment:Environment){const facts=await environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>(await tx.client.query("SELECT request_id,array_agg(logical_step_id ORDER BY CASE logical_step_id WHEN 'OCR' THEN 0 WHEN 'TRANSLATE' THEN 1 WHEN 'CLEANUP' THEN 2 ELSE 3 END) AS stages,bool_and(state='SUCCEEDED') AS succeeded FROM executions WHERE account_id=$1 GROUP BY request_id",[environment.local.accountId])).rows);expect(facts.length).toBeGreaterThan(0);for(const fact of facts){expect(fact.stages).toEqual(['OCR','TRANSLATE','CLEANUP','TYPESET']);expect(fact.succeeded).toBe(true);}return facts.map(fact=>fact.stages);}
async function finishProject(page:Page,touch:boolean,info:TestInfo,name:string){
  await activate(page.getByRole('button',{name:'저장하고 나가기'}),touch);const exit=page.getByRole('dialog',{name:'프로젝트를 보관하고 나가기'});await activate(exit.getByRole('button',{name:'최신 프로젝트 파일 만들기'}),touch);await expect(exit.getByRole('button',{name:'프로젝트 파일 다운로드',exact:true})).toBeEnabled();const downloadEvent=page.waitForEvent('download');await activate(exit.getByRole('button',{name:'프로젝트 파일 다운로드',exact:true}),touch);const file=artifact(info,`${name}.manga-project.zip`);await (await downloadEvent).saveAs(file);await expect(exit.getByRole('button',{name:'파일을 보관했어요 · 종료'})).toBeEnabled();await activate(exit.getByRole('button',{name:'파일을 보관했어요 · 종료'}),touch);await expect(page.getByRole('button',{name:'새 프로젝트 만들기'})).toBeVisible();return file;
}
async function healthy(page:Page,environment:Environment,jsErrors:string[]){expect(environment.errors).toEqual([]);expect(jsErrors).toEqual([]);await expect(page.getByRole('alert')).toHaveCount(0);expect(await page.evaluate(()=>document.documentElement.scrollWidth>window.innerWidth)).toBe(false);}

// These records belong to the owned synthetic fixture. Their labels and amounts are not actual provider or operating-cost evidence.
async function exitAckOriginalFacts(environment:Environment){
  return environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>({
    account:(await tx.client.query('SELECT free_started_count,balance_credit::text AS balance_credit FROM accounts WHERE account_id=$1',[environment.local.accountId])).rows,
    reservations:(await tx.client.query('SELECT request_id,state FROM free_reservations WHERE account_id=$1 ORDER BY request_id',[environment.local.accountId])).rows,
    requests:(await tx.client.query('SELECT request_id,state,first_start_at FROM processing_requests WHERE account_id=$1 ORDER BY request_id',[environment.local.accountId])).rows,
    executions:(await tx.client.query('SELECT execution_id,request_id,logical_step_id,input_digest,state,dispatch_attempted_at,start_confirmed_at,finished_confirmed_at FROM executions WHERE account_id=$1 ORDER BY execution_id',[environment.local.accountId])).rows,
    costs:(await tx.client.query('SELECT cost_item_id,execution_id,state,actual_usd::text AS actual_usd,usage_ref,rate_version,confirmed_at FROM cost_items WHERE account_id=$1 ORDER BY cost_item_id',[environment.local.accountId])).rows,
    settlements:(await tx.client.query('SELECT cost_item_id,ledger_entry_id,debit_credit::text AS debit_credit,mode,basis_version FROM settlements WHERE account_id=$1 ORDER BY cost_item_id',[environment.local.accountId])).rows,
    results:(await tx.client.query('SELECT p.current_result_id,p.result_revision,r.original_asset_id,r.cleaned_asset_id,r.edit_data FROM workspace_pages p JOIN results r ON r.account_id=p.account_id AND r.result_id=p.current_result_id WHERE p.account_id=$1 AND NOT p.excluded ORDER BY p.display_order',[environment.local.accountId])).rows,
    sessions:(await tx.client.query('SELECT session_id,revoked_at FROM app_sessions WHERE account_id=$1 ORDER BY session_id',[environment.local.accountId])).rows
  }));
}
async function exitAckState(environment:Environment,command:WorkspaceCommand){
  return environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>({
    context:(await tx.client.query('SELECT context_id,generation,lifecycle,owner_tab_id,owner_revision FROM workspace_contexts WHERE account_id=$1 AND context_id=$2',[environment.local.accountId,command.target.contextId])).rows,
    exits:(await tx.client.query('SELECT exit_operation_id,context_id,context_generation,purpose,state FROM exit_operations WHERE account_id=$1 AND context_id=$2 ORDER BY exit_operation_id',[environment.local.accountId,command.target.contextId])).rows,
    receipts:(await tx.client.query('SELECT command_id,operation_kind,operation_ref FROM command_receipts WHERE account_id=$1 AND command_id=$2',[environment.local.accountId,command.commandId])).rows,
    attestations:(await tx.client.query('SELECT attestation_id FROM file_attestations WHERE account_id=$1 AND context_id=$2',[environment.local.accountId,command.target.contextId])).rows
  }));
}
async function observeBeginExit(page:Page,options:{loseFirstBody?:boolean;onAcknowledged?:()=>void}={}){
  const commands:WorkspaceCommand[]=[];const begins:{body:string;command:WorkspaceCommand;reply:CommandReply;status:number}[]=[];
  await page.route('**/api/v1/commands',async route=>{
    const body=route.request().postData();expect(typeof body).toBe('string');const command=JSON.parse(body!) as WorkspaceCommand;commands.push(command);
    if(command.operation.kind!=='BEGIN_EXIT'){await route.continue();return;}
    const response=await route.fetch();const reply=await response.json() as CommandReply;const ordinal=begins.length;
    expect(response.status()).toBe(200);expect(reply.commandId).toBe(command.commandId);expect(reply.disposition).toBe(ordinal===0?'ACCEPTED':'EXISTING');expect(reply.operationRef.kind).toBe('EXIT');expect(reply.operationRef.id).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    begins.push({body:body!,command,reply,status:response.status()});if(ordinal===0)options.onAcknowledged?.();
    if(ordinal===0&&options.loseFirstBody){await route.fulfill({response,headers:{...response.headers(),'content-type':'application/json','content-length':'1'},body:'{'});return;}
    await route.fulfill({response});
  });
  return {commands,begins};
}

test('BEGIN_EXIT SAVE_AND_EXIT reuses the original command after a lost JSON body and preserves the draft',async({page,environment},info)=>{
  const touch=Boolean(info.project.use.hasTouch);const jsErrors:string[]=[];page.on('pageerror',error=>jsErrors.push(error.message));await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch);await settings(page,environment,touch);await activate(page.getByRole('button',{name:'페이지 번역',exact:true}),touch);const draft=page.getByRole('textbox',{name:'1번 대사 번역문'});await expect(draft).toHaveValue('합성 번역');await expect(draft).toBeEnabled();
  await expect.poll(async()=>(await exitAckOriginalFacts(environment)).requests.map(row=>row.state)).toEqual(['COMPLETED']);await assertFourStages(environment);await typeValue(draft,'BEGIN_EXIT 응답 유실에도 보존할 미반영 초안',touch);const before=await exitAckOriginalFacts(environment);expect(environment.local.provider.calls).toHaveLength(2);expect(before.results[0]).toMatchObject({edit_data:{blocks:[{translatedText:{value:'합성 번역'}}]}});
  const trace=await observeBeginExit(page,{loseFirstBody:true});await activate(page.getByRole('button',{name:'저장하고 나가기',exact:true}),touch);await expect(page.getByRole('alert')).toContainText('TRANSPORT_UNCONFIRMED');await expect.poll(()=>trace.begins.length).toBe(1);const first=trace.begins[0];const committed=await exitAckState(environment,first.command);expect(committed.context).toMatchObject([{context_id:first.command.target.contextId,generation:first.command.target.contextGeneration,lifecycle:'EXITING'}]);expect(committed.exits).toEqual([{exit_operation_id:first.reply.operationRef.id,context_id:first.command.target.contextId,context_generation:first.command.target.contextGeneration,purpose:'SAVE_AND_EXIT',state:'WAITING_SAFE'}]);expect(committed.receipts).toEqual([{command_id:first.command.commandId,operation_kind:'BEGIN_EXIT',operation_ref:first.reply.operationRef}]);
  await activate(page.getByRole('button',{name:'같은 요청 다시 확인',exact:true}),touch);await expect.poll(()=>trace.begins.length).toBe(2);expect(trace.begins.map(item=>item.body)).toEqual([first.body,first.body]);expect(trace.begins[1].reply).toMatchObject({commandId:first.command.commandId,disposition:'EXISTING',operationRef:first.reply.operationRef});const recovered=await exitAckState(environment,first.command);expect(recovered.exits).toEqual(committed.exits);expect(recovered.receipts).toEqual(committed.receipts);expect(await exitAckOriginalFacts(environment)).toEqual(before);expect(environment.local.provider.calls).toHaveLength(2);
  await writeFile(artifact(info,'BEGIN_EXIT-save-and-exit-server-ack.json'),JSON.stringify({mode:'SYNTHETIC',physicalDeviceEvidence:false,fault:'ACTUAL_ACK_THEN_INVALID_JSON_BODY',originalCommandId:first.command.commandId,originalExitId:first.reply.operationRef.id,identicalRetryBody:true,serverDispositions:trace.begins.map(item=>item.reply.disposition),exitCount:recovered.exits.length,originalFactsUnchanged:true},null,2));
  const dialog=page.getByRole('dialog',{name:'프로젝트를 보관하고 나가기'});await expect(dialog).toBeVisible();await expect(draft).toHaveValue('BEGIN_EXIT 응답 유실에도 보존할 미반영 초안');await activate(dialog.getByRole('button',{name:'작업으로 돌아가기',exact:true}),touch);await expect(dialog).not.toBeVisible();const cancelled=await exitAckState(environment,first.command);expect(cancelled.context).toMatchObject([{context_id:first.command.target.contextId,generation:first.command.target.contextGeneration,lifecycle:'OPEN'}]);expect(cancelled.exits).toMatchObject([{exit_operation_id:first.reply.operationRef.id,state:'CANCELLED'}]);expect(cancelled.receipts).toEqual(committed.receipts);expect(cancelled.attestations).toEqual([]);expect(trace.commands.filter(command=>command.operation.kind==='BEGIN_EXIT')).toHaveLength(2);expect(trace.commands.filter(command=>command.operation.kind==='CANCEL_EXIT')).toHaveLength(1);expect(trace.commands.filter(command=>['DECLARE_DRAFT_BARRIER','CAPTURE_PROJECT_FILE','ATTEST_PROJECT_FILE'].includes(command.operation.kind))).toEqual([]);await expect(draft).toHaveValue('BEGIN_EXIT 응답 유실에도 보존할 미반영 초안');expect(await exitAckOriginalFacts(environment)).toEqual(before);expect(environment.local.provider.calls).toHaveLength(2);await healthy(page,environment,jsErrors);
});

test('BEGIN_EXIT LOGOUT_CURRENT keeps the acknowledged dialog when the first session refresh fails',async({page,environment},info)=>{
  const touch=Boolean(info.project.use.hasTouch);const jsErrors:string[]=[];page.on('pageerror',error=>jsErrors.push(error.message));
  // Only this fixture pauses browser timers and suppresses SSE. The API/worker clock, product deadlines and owner checks stay real.
  const browserEpoch=Date.now();await page.clock.install({time:browserEpoch});await page.clock.pauseAt(browserEpoch+1000);let clockPaused=true;await page.route('**/api/v1/workspaces/*/events',route=>route.abort());
  try{
    await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch);const before=await exitAckOriginalFacts(environment);expect(environment.local.provider.calls).toHaveLength(0);await activate(page.getByRole('button',{name:'계정',exact:true}),touch);
    let refreshArmed=false;let refreshFaults=0;let logoutPosts=0;const order:string[]=[];const browserBeginResponses:{commandId:string;status:number}[]=[];page.on('request',request=>{if(request.method()==='POST'&&new URL(request.url()).pathname==='/api/v1/auth/logout-current')logoutPosts++;});page.on('response',response=>{if(new URL(response.url()).pathname!=='/api/v1/commands')return;const command=response.request().postDataJSON() as WorkspaceCommand;if(command.operation.kind==='BEGIN_EXIT'){browserBeginResponses.push({commandId:command.commandId,status:response.status()});order.push('BEGIN_EXIT_BROWSER_RESPONSE');}});
    await page.route('**/api/v1/session',async route=>{if(!refreshArmed||refreshFaults>0){await route.continue();return;}order.push('SESSION_REFRESH_REQUEST');const response=await route.fetch();const session=await response.json() as {authenticated:boolean;account:{serverTime:string}};expect(response.status()).toBe(200);expect(session.authenticated).toBe(true);order.push('SESSION_REFRESH_ACTUAL_200');refreshFaults++;refreshArmed=false;await route.fulfill({response,status:503,json:{code:'DEPENDENCY_UNAVAILABLE',message:'BEGIN_EXIT 회귀: 세션 조회 응답 확인 불가',nextAction:'REFETCH',serverTime:session.account.serverTime}});order.push('SESSION_REFRESH_503');});
    const trace=await observeBeginExit(page,{onAcknowledged:()=>{order.push('BEGIN_EXIT_SERVER_ACK');refreshArmed=true;}});await activate(page.getByRole('button',{name:'현재 앱 로그인 종료',exact:true}),touch);await expect.poll(()=>refreshFaults).toBe(1);await expect(page.getByRole('alert')).toContainText('DEPENDENCY_UNAVAILABLE');await expect.poll(()=>[...order]).toEqual(['BEGIN_EXIT_SERVER_ACK','BEGIN_EXIT_BROWSER_RESPONSE','SESSION_REFRESH_REQUEST','SESSION_REFRESH_ACTUAL_200','SESSION_REFRESH_503']);await expect.poll(()=>trace.begins.length).toBe(1);const first=trace.begins[0];expect(browserBeginResponses).toEqual([{commandId:first.command.commandId,status:200}]);const committed=await exitAckState(environment,first.command);expect(first.command.operation).toEqual({kind:'BEGIN_EXIT',payload:{purpose:'LOGOUT_CURRENT'}});expect(committed.context).toMatchObject([{context_id:first.command.target.contextId,generation:first.command.target.contextGeneration,lifecycle:'EXITING'}]);expect(committed.exits).toEqual([{exit_operation_id:first.reply.operationRef.id,context_id:first.command.target.contextId,context_generation:first.command.target.contextGeneration,purpose:'LOGOUT_CURRENT',state:'WAITING_SAFE'}]);expect(committed.receipts).toEqual([{command_id:first.command.commandId,operation_kind:'BEGIN_EXIT',operation_ref:first.reply.operationRef}]);expect(committed.attestations).toEqual([]);expect(logoutPosts).toBe(0);expect(await exitAckOriginalFacts(environment)).toEqual(before);
    await writeFile(artifact(info,'BEGIN_EXIT-logout-current-refresh-failure.json'),JSON.stringify({mode:'SYNTHETIC',physicalDeviceEvidence:false,fault:'ACTUAL_BEGIN_EXIT_ACK_THEN_SEND_SESSION_REFRESH_503',browserTimersPaused:true,sseSuppressed:true,apiWorkerClockUnchanged:true,order,originalCommandId:first.command.commandId,originalExitId:first.reply.operationRef.id,beginExitCount:trace.begins.length,refreshFaults,exitCount:committed.exits.length,attestations:committed.attestations.length,logoutPosts,originalFactsUnchanged:true},null,2));
    const dialog=page.getByRole('dialog',{name:'저장하고 현재 로그인 종료'});await expect(dialog).toBeVisible();await expect(dialog.getByRole('button',{name:'최신 프로젝트 파일 만들기',exact:true})).toBeEnabled();await page.clock.resume();clockPaused=false;await activate(dialog.getByRole('button',{name:'최신 프로젝트 파일 만들기',exact:true}),touch);await expect(dialog.getByRole('button',{name:'프로젝트 파일 다운로드',exact:true})).toBeEnabled();const prepared=await exitAckState(environment,first.command);expect(prepared.exits).toMatchObject([{exit_operation_id:first.reply.operationRef.id,purpose:'LOGOUT_CURRENT',state:'FILE_REQUESTED'}]);expect(prepared.receipts).toEqual(committed.receipts);expect(prepared.attestations).toEqual([]);expect(trace.begins).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='BEGIN_EXIT')).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='DECLARE_DRAFT_BARRIER')).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='CAPTURE_PROJECT_FILE')).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='ATTEST_PROJECT_FILE')).toEqual([]);expect(refreshFaults).toBe(1);expect(logoutPosts).toBe(0);expect(await exitAckOriginalFacts(environment)).toEqual(before);expect(environment.local.provider.calls).toHaveLength(0);await healthy(page,environment,jsErrors);
  }finally{if(clockPaused)await page.clock.resume();}
});

test('BEGIN_EXIT same-command recovery stays hidden after an actual other-tab HANDOFF',async({page,context,environment},info)=>{
  const touch=Boolean(info.project.use.hasTouch);const jsErrors:string[]=[];page.on('pageerror',error=>jsErrors.push(error.message));await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch);const before=await exitAckOriginalFacts(environment);const trace=await observeBeginExit(page,{loseFirstBody:true});await activate(page.getByRole('button',{name:'저장하고 나가기',exact:true}),touch);await expect(page.getByRole('alert')).toContainText('TRANSPORT_UNCONFIRMED');await expect.poll(()=>trace.begins.length).toBe(1);const first=trace.begins[0];const committed=await exitAckState(environment,first.command);expect(committed.exits).toHaveLength(1);expect(committed.receipts).toEqual([{command_id:first.command.commandId,operation_kind:'BEGIN_EXIT',operation_ref:first.reply.operationRef}]);
  const other=await context.newPage();other.on('pageerror',error=>jsErrors.push(error.message));const handoffs:WorkspaceCommand[]=[];await other.route('**/api/v1/commands',async route=>{const command=route.request().postDataJSON() as WorkspaceCommand;if(command.operation.kind==='HANDOFF')handoffs.push(command);await route.continue();});await other.goto(environment.origin);await activate(other.getByRole('button',{name:'이 탭에서 편집하기',exact:true}),touch);await expect.poll(()=>handoffs.length).toBe(1);await expect(other.locator('.ownership-note').filter({hasText:'다른 탭에서 이 프로젝트를 편집하고 있어요.'})).toHaveCount(0);await expect(page.locator('.ownership-note').filter({hasText:'다른 탭에서 이 프로젝트를 편집하고 있어요.'})).toBeVisible();
  await activate(page.getByRole('button',{name:'같은 요청 다시 확인',exact:true}),touch);await expect.poll(()=>trace.begins.length).toBe(2);expect(trace.begins.map(item=>item.body)).toEqual([first.body,first.body]);expect(trace.begins[1].reply).toMatchObject({commandId:first.command.commandId,disposition:'EXISTING',operationRef:first.reply.operationRef});const observed=await exitAckState(environment,first.command);expect(observed.exits).toEqual(committed.exits);expect(observed.receipts).toEqual(committed.receipts);expect(observed.context).toMatchObject([{context_id:first.command.target.contextId,generation:first.command.target.contextGeneration,lifecycle:'EXITING',owner_tab_id:handoffs[0].target.tabId}]);expect(observed.context[0].owner_tab_id).not.toBe(first.command.target.tabId);expect(BigInt(observed.context[0].owner_revision)).toBeGreaterThan(BigInt(first.command.target.expectedOwnerRevision));expect(observed.attestations).toEqual([]);expect(trace.commands.filter(command=>['CANCEL_EXIT','DECLARE_DRAFT_BARRIER','CAPTURE_PROJECT_FILE','ATTEST_PROJECT_FILE'].includes(command.operation.kind))).toEqual([]);expect(await exitAckOriginalFacts(environment)).toEqual(before);expect(environment.local.provider.calls).toHaveLength(0);
  await writeFile(artifact(info,'BEGIN_EXIT-old-owner-recovery.json'),JSON.stringify({mode:'SYNTHETIC',physicalDeviceEvidence:false,originalCommandId:first.command.commandId,originalExitId:first.reply.operationRef.id,identicalRetryBody:true,actualOtherTabHandoff:true,exitCount:observed.exits.length,receiptCount:observed.receipts.length,followupExitCommands:0,originalFactsUnchanged:true},null,2));await expect(page.getByRole('dialog',{name:'프로젝트를 보관하고 나가기'})).not.toBeVisible();await expect(page.getByRole('dialog',{name:'저장하고 현재 로그인 종료'})).not.toBeVisible();await healthy(page,environment,jsErrors);await expect(other.getByRole('alert')).toHaveCount(0);
});

test('BEGIN_EXIT acknowledged dialog closes when an actual other-tab HANDOFF removes its owner',async({page,context,environment},info)=>{
  const touch=Boolean(info.project.use.hasTouch);const jsErrors:string[]=[];page.on('pageerror',error=>jsErrors.push(error.message));await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch);const before=await exitAckOriginalFacts(environment);const trace=await observeBeginExit(page);await activate(page.getByRole('button',{name:'저장하고 나가기',exact:true}),touch);const dialog=page.getByRole('dialog',{name:'프로젝트를 보관하고 나가기'});await expect(dialog).toBeVisible();expect(trace.begins).toHaveLength(1);const first=trace.begins[0];const committed=await exitAckState(environment,first.command);expect(committed.exits).toHaveLength(1);expect(committed.receipts).toEqual([{command_id:first.command.commandId,operation_kind:'BEGIN_EXIT',operation_ref:first.reply.operationRef}]);
  await activate(dialog.getByRole('button',{name:'최신 프로젝트 파일 만들기',exact:true}),touch);await expect(dialog.getByRole('button',{name:'프로젝트 파일 다운로드',exact:true})).toBeEnabled();const prepared=await exitAckState(environment,first.command);expect(prepared.exits).toMatchObject([{exit_operation_id:first.reply.operationRef.id,state:'FILE_REQUESTED'}]);expect(prepared.receipts).toEqual(committed.receipts);const exports=await environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>(await tx.client.query('SELECT export_id,kind,state FROM exports WHERE account_id=$1 AND context_id=$2 ORDER BY export_id',[environment.local.accountId,first.command.target.contextId])).rows);expect(exports).toHaveLength(1);expect(exports[0]).toMatchObject({kind:'PROJECT_FILE',state:'AVAILABLE'});const exportId=exports[0].export_id as string;const exportPath=`/api/v1/exports/${exportId}`;
  const exportRequests:Request[]=[];page.on('request',request=>{if(request.method()==='GET'&&new URL(request.url()).pathname===exportPath)exportRequests.push(request);});const heldResponses:{request:Request;projection:ExportProjection}[]=[];let releaseLateResponse:()=>void=()=>undefined;const lateRelease=new Promise<void>(resolve=>{releaseLateResponse=resolve;});await page.route(`**${exportPath}`,async route=>{const response=await route.fetch();const projection=await response.json() as ExportProjection;expect(response.status()).toBe(200);expect(projection.operationRef).toEqual({kind:'EXPORT',id:exportId});expect(projection.state).toBe('AVAILABLE');if(heldResponses.length===0){heldResponses.push({request:route.request(),projection});await lateRelease;}await route.fulfill({response});});
  try{
    await expect.poll(()=>heldResponses.length).toBe(1);const other=await context.newPage();other.on('pageerror',error=>jsErrors.push(error.message));const handoffs:WorkspaceCommand[]=[];await other.route('**/api/v1/commands',async route=>{const command=route.request().postDataJSON() as WorkspaceCommand;if(command.operation.kind==='HANDOFF')handoffs.push(command);await route.continue();});await other.goto(environment.origin);await activate(other.getByRole('button',{name:'이 탭에서 편집하기',exact:true}),touch);await expect.poll(()=>handoffs.length).toBe(1);await expect(other.locator('.ownership-note').filter({hasText:'다른 탭에서 이 프로젝트를 편집하고 있어요.'})).toHaveCount(0);await expect(page.locator('.ownership-note').filter({hasText:'다른 탭에서 이 프로젝트를 편집하고 있어요.'})).toBeVisible();const observed=await exitAckState(environment,first.command);expect(observed.context).toMatchObject([{context_id:first.command.target.contextId,generation:first.command.target.contextGeneration,lifecycle:'EXITING',owner_tab_id:handoffs[0].target.tabId}]);expect(observed.context[0].owner_tab_id).not.toBe(first.command.target.tabId);expect(BigInt(observed.context[0].owner_revision)).toBeGreaterThan(BigInt(first.command.target.expectedOwnerRevision));expect(observed.exits).toEqual(prepared.exits);expect(observed.receipts).toEqual(committed.receipts);expect(observed.attestations).toEqual([]);
    const pollsAtOwnerLoss=exportRequests.length;const commandsAtOwnerLoss=trace.commands.length;const lateResponse=page.waitForResponse(response=>response.request()===heldResponses[0].request);releaseLateResponse();const delivered=await lateResponse;expect(await delivered.json()).toEqual(heldResponses[0].projection);
    // 1.6 seconds exceeds two existing 700ms poll intervals; this is a bounded leak observation, not a product deadline.
    await page.waitForTimeout(1600);expect(exportRequests).toHaveLength(pollsAtOwnerLoss);expect(trace.commands.slice(commandsAtOwnerLoss)).toEqual([]);expect(trace.begins).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='CANCEL_EXIT'||command.operation.kind==='ATTEST_PROJECT_FILE')).toEqual([]);expect(trace.commands.filter(command=>command.operation.kind==='DECLARE_DRAFT_BARRIER')).toHaveLength(1);expect(trace.commands.filter(command=>command.operation.kind==='CAPTURE_PROJECT_FILE')).toHaveLength(1);expect(await exitAckOriginalFacts(environment)).toEqual(before);expect(environment.local.provider.calls).toHaveLength(0);
    await writeFile(artifact(info,'BEGIN_EXIT-owner-loss-after-ack.json'),JSON.stringify({mode:'SYNTHETIC',physicalDeviceEvidence:false,originalCommandId:first.command.commandId,originalExitId:first.reply.operationRef.id,originalExportId:exportId,dialogWasVisibleBeforeHandoff:true,filePreparedBeforeHandoff:true,actualOtherTabHandoff:true,lateOriginalGetDelivered:true,originalGetState:heldResponses[0].projection.state,observationMilliseconds:1600,pollRequestsAtOwnerLoss:pollsAtOwnerLoss,pollRequestsAfterObservation:exportRequests.length,exitCount:observed.exits.length,receiptCount:observed.receipts.length,followupExitCommands:0,originalFactsUnchanged:true},null,2));await expect(dialog).not.toBeVisible();await expect(page.locator('.export-status')).toHaveCount(0);await expect(page.getByRole('button',{name:'프로젝트 파일 다운로드',exact:true})).toHaveCount(0);await healthy(page,environment,jsErrors);await expect(other.getByRole('alert')).toHaveCount(0);
  }finally{releaseLateResponse();}
});

