async function pageUploadRetry(page:Page,touch:boolean){const inDialog=pageUploadDialog(page).getByRole('button',{name:'같은 요청 다시 확인',exact:true});const control=await inDialog.count()>0?inDialog:page.getByRole('button',{name:'같은 요청 다시 확인',exact:true});await activate(control,touch);}
async function pageUploadHoldWorkspace(page:Page){
  let release:()=>void=()=>undefined;const joined=new Promise<void>(resolve=>{release=resolve;});
  const observed:{request:Request;projection:import('../../packages/contracts/src/api.js').WorkspaceProjection}[]=[];let first=true;
  const pattern='**/api/v1/workspaces/*';const pending=new Set<Promise<void>>();const failures:unknown[]=[];let disposal:Promise<void>|null=null;
  const handler=(route:import('@playwright/test').Route)=>{
    const task=(async()=>{
      if(route.request().method()!=='GET'){await route.continue();return;}
      const response=await route.fetch();expect(response.status()).toBe(200);const projection=await response.json() as import('../../packages/contracts/src/api.js').WorkspaceProjection;observed.push({request:route.request(),projection});
      if(first){first=false;await joined;}await route.fulfill({response});
    })();
    pending.add(task);
    // Observe every rejection immediately, preserve it for disposal, and return the original task to Playwright.
    void task.then(()=>{pending.delete(task);},error=>{pending.delete(task);failures.push(error);});
    return task;
  };
  await page.route(pattern,handler);
  const dispose=()=>{
    if(disposal!==null)return disposal;
    release();
    disposal=(async()=>{
      // Remove only this helper; the server remains alive until all already-started fetch/fulfill work joins.
      const removed=await Promise.allSettled([page.unroute(pattern,handler)]);
      while(pending.size>0)await Promise.allSettled([...pending]);
      const errors=[...failures];if(removed[0].status==='rejected')errors.push(removed[0].reason);
      if(errors.length===1)throw errors[0];
      if(errors.length>1)throw new AggregateError(errors,'PAGE_UPLOAD workspace route drain failed');
    })();
    return disposal;
  };
  return {release,observed,dispose};
}
