    await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch,2);await settings(page,environment,touch);const canonical=await zipCanonicalPages(environment),before=await exitAckOriginalFacts(environment);expect(environment.local.provider.calls).toHaveLength(0);
