type ManualEditAckCommand=WorkspaceCommand&{operation:Extract<WorkspaceCommand['operation'],{kind:'MANUAL_EDIT'}>};
type ManualEditAckEntry={body:string;command:ManualEditAckCommand;reply:CommandReply;path:string};
async function observeManualEditAck(page:Page,options:{loseFirstBody?:()=>boolean;onAcknowledged?:(entry:ManualEditAckEntry)=>void}={}){
  const commands:WorkspaceCommand[]=[],edits:ManualEditAckEntry[]=[];
  await page.route('**/api/v1/commands',async route=>{
    const body=route.request().postData();expect(typeof body).toBe('string');const command=JSON.parse(body!) as WorkspaceCommand;commands.push(command);
    if(command.operation.kind!=='MANUAL_EDIT'){await route.continue();return;}
    const repeated=edits.some(entry=>entry.command.commandId===command.commandId),response=await route.fetch(),reply=await response.json() as CommandReply;
    expect(response.status()).toBe(200);expect(reply.commandId).toBe(command.commandId);expect(reply.disposition).toBe(repeated?'EXISTING':'APPLIED');expect(reply.operationRef).toEqual({kind:'WORKSPACE',id:command.target.contextId});expect(reply.observedRevision).toMatch(/^(0|[1-9]\d*)$/);
    const entry:ManualEditAckEntry={body:body!,command:command as ManualEditAckCommand,reply,path:new URL(route.request().url()).pathname};edits.push(entry);if(!repeated)options.onAcknowledged?.(entry);
    if(!repeated&&options.loseFirstBody?.()){await route.fulfill({response,headers:{...response.headers(),'content-type':'application/json','content-length':'1'},body:'{'});return;}
    await route.fulfill({response});
  });
  return {commands,edits};
}
async function manualEditAckFacts(environment:Environment,command:ManualEditAckCommand){
  return environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>({
    receipt:(await tx.client.query('SELECT command_id,operation_kind,operation_ref FROM command_receipts WHERE account_id=$1 AND command_id=$2',[environment.local.accountId,command.commandId])).rows,
    history:(await tx.client.query('SELECT history_id,before_result_id,after_result_id,validity,protected_delta FROM manual_history WHERE account_id=$1 AND context_id=$2 AND page_lineage_id=$3 ORDER BY history_id',[environment.local.accountId,command.target.contextId,command.operation.payload.pageId])).rows
  }));
}
async function prepareManualEditAck(page:Page,environment:Environment,touch:boolean,count:number){
  const jsErrors:string[]=[];page.on('pageerror',error=>jsErrors.push(error.message));await page.clock.install({time:Date.now()});await page.route('**/api/v1/workspaces/*/events',route=>route.abort());
  await signInAndCreate(page,environment,touch);await addOwnedPages(page,touch,count);await settings(page,environment,touch);
  for(let index=0;index<count;index++){await activate(page.locator('.page-select').nth(index),touch);await expect(page.locator('.page-work-heading h2')).toHaveText('owned-'+(index+1)+'.png');await activate(page.getByRole('button',{name:'페이지 번역',exact:true}),touch);await expect(page.getByRole('textbox',{name:'1번 대사 번역문'})).toHaveValue('합성 번역');await expect(page.getByRole('textbox',{name:'1번 대사 번역문'})).toBeEnabled();}
  await expect.poll(async()=>(await exitAckOriginalFacts(environment)).requests.map(row=>row.state)).toEqual(Array.from({length:count},()=> 'COMPLETED'));await assertFourStages(environment);expect(environment.local.provider.calls).toHaveLength(count*2);
  await activate(page.locator('.page-select').nth(0),touch);await expect(page.locator('.page-work-heading h2')).toHaveText('owned-1.png');await expect(page.getByRole('textbox',{name:'1번 대사 번역문'})).toHaveValue('합성 번역');await expect(page.getByRole('textbox',{name:'1번 대사 번역문'})).toBeEnabled();
  const epoch=await page.evaluate(()=>Date.now());await page.clock.pauseAt(epoch+1000);return {jsErrors};
}

