    for(const mode of ['PAGE_REVISION','PATCH','FONT_DEPENDENCY'] as const){pageMode=mode;const count=reads.length;await page.clock.fastForward(5000);await expect.poll(()=>reads.length).toBeGreaterThan(count);expect(reads.at(-1)?.mode).toBe(mode);expect(reads.at(-1)?.actualRevision).toBe(committed.result_revision);expect(projections.at(-1)?.workspaceRevision).toBe(first.reply.observedRevision);expect(projections.at(-1)?.pagesInOrder.find(summary=>summary.pageLineageId===first.command.operation.payload.pageId)?.resultRevision).toBe(committed.result_revision);await expect(note).toBeVisible();await expect(translated).toHaveValue('legacy 원 수정');await expect(siblingText).toHaveValue('보존할 같은 페이지 초안');await expect(siblingNote).toBeVisible();await expect(page.getByRole('button',{name:'같은 요청 다시 확인',exact:true})).toHaveCount(0);expect(trace.edits).toHaveLength(2);expect(await manualEditAckFacts(environment,first.command)).toEqual(facts);}
    pageMode=null;const beforeRecoveryReads=reads.length;await page.clock.fastForward(5000);await expect.poll(()=>reads.length).toBeGreaterThan(beforeRecoveryReads);expect(reads.at(-1)?.mode).toBeNull();await expect(note).toHaveCount(0);await expect(translated).toHaveValue('legacy 원 수정');await expect(firstRow.getByRole('button',{name:'비교했어요 · 내 초안을 적용할 준비',exact:true})).toHaveCount(0);await expect(siblingText).toHaveValue('보존할 같은 페이지 초안');await expect(siblingNote).toBeVisible();await expect(siblingRow.getByRole('button',{name:'수정 반영',exact:true})).toBeDisabled();await expect(siblingRow.getByRole('button',{name:'비교했어요 · 내 초안을 적용할 준비',exact:true})).toBeVisible();expect((await currentResults(environment))[0].edit_data).toEqual(committed.edit_data);expect(await manualEditAckFacts(environment,first.command)).toEqual(facts);expect(trace.edits).toHaveLength(2);
