async function installManualConfirmedBaseline(environment:Environment){
  return environment.local.runtime.options.api.accountTransaction(environment.local.accountId,async tx=>{
    const original=(await currentResultsForTx()).rows[0];expect(original.edit_data.blocks).toHaveLength(1);
    const data=structuredClone(original.edit_data);data.blocks[0].sourceText.status='USER_CONFIRMED';data.blocks[0].translatedText.status='USER_CONFIRMED';
    const id=randomUUID(),revision=(BigInt(original.result_revision)+1n).toString();
    expect((await tx.client.query("INSERT INTO results(account_id,result_id,context_id,page_lineage_id,result_revision,original_asset_id,cleaned_asset_id,render_asset_id,protected_edit_data_ref,origin,edit_data) SELECT account_id,$3,context_id,page_lineage_id,$4,original_asset_id,cleaned_asset_id,NULL,$3::uuid::text,'IMPORT_BASELINE',$5::jsonb FROM results WHERE account_id=$1 AND result_id=$2",[environment.local.accountId,original.result_id,id,revision,JSON.stringify(data)])).rowCount).toBe(1);
    expect((await tx.client.query('UPDATE workspace_pages SET current_result_id=$4,result_revision=$5,revision=revision+1 WHERE account_id=$1 AND context_id=$2 AND page_lineage_id=$3 AND current_result_id=$6 AND result_revision=$7',[environment.local.accountId,original.context_id,original.page_lineage_id,id,revision,original.result_id,original.result_revision])).rowCount).toBe(1);
    expect((await tx.client.query('UPDATE workspace_contexts SET workspace_revision=workspace_revision+1 WHERE account_id=$1 AND context_id=$2',[environment.local.accountId,original.context_id])).rowCount).toBe(1);
    expect((await tx.client.query<ResultRow>('SELECT * FROM results WHERE account_id=$1 AND result_id=$2',[environment.local.accountId,original.result_id])).rows[0]).toEqual(original);
    const installed=(await tx.client.query<ResultRow>('SELECT * FROM results WHERE account_id=$1 AND result_id=$2',[environment.local.accountId,id])).rows[0];expect(installed.edit_data).toEqual(data);return installed;
    function currentResultsForTx(){return tx.client.query<ResultRow>("SELECT r.* FROM results r JOIN workspace_pages p ON p.account_id=r.account_id AND p.current_result_id=r.result_id JOIN workspace_contexts c ON c.account_id=p.account_id AND c.context_id=p.context_id WHERE p.account_id=$1 AND c.lifecycle='OPEN' AND NOT p.excluded ORDER BY p.display_order",[environment.local.accountId]);}
  });
}
