  await activate(page.getByRole('button',{name:'되돌리기',exact:true}),touch);await expect(row.getByRole('spinbutton',{name:'1번 대사 식자 영역 너비'})).toHaveValue('180');expect((await currentResults(environment))[0].edit_data).toEqual(saved.edit_data);
  await activate(page.getByRole('button',{name:'다시 적용',exact:true}),touch);await expect(row.locator('summary')).toHaveText('1번 대사 식자 영역 · 원문 영역 기준');await expect(row.getByRole('button',{name:'원문 영역 기준으로 되돌리기',exact:true})).toBeDisabled();expect((await currentResults(environment))[0].edit_data.renderSpecification!.blocks[0].typesetBox).toBeUndefined();
