test('MANUAL_TARGET_ORIENTATION retains target-only draft through lost ACK and mismatched read before same-request recovery',async({page,environment},info)=>{
  const touch=Boolean(info.project.use.hasTouch),standard=environment.local.provider.success.bind(environment.local.provider);environment.local.provider.success=input=>{const observation=standard(input);if(input.stage==='OCR'&&input.initialData.blocks.length===0)observation.data!.blocks[0].geometry.orientation='VERTICAL';return observation;};
  const {jsErrors}=await prepareManualEditAck(page,environment,touch,1);let paused=true,loseBody=true,pageMode:'TARGET'|'SOURCE'|'SPECIFICATION'|'GOOD'='TARGET';const reads:{mode:string;revision:string}[]=[];
  try{
    const baseline=await installManualConfirmedBaseline(environment);await page.clock.fastForward(5000);await expect(page.locator('.page-work-heading p')).toContainText('결과 버전 '+baseline.result_revision+' ·');const processing=await exitAckOriginalFacts(environment),row=page.locator('.dialogue-row').first(),direction=row.getByRole('combobox',{name:'1번 대사 번역문 쓰기 방향'}),note=row.getByText('이 탭에 미반영 초안이 있어요.',{exact:true});
    await page.route('**/api/v1/workspaces/*/pages/*',async route=>{const response=await route.fetch(),actual=await response.json() as PageView,delivered=structuredClone(actual);expect(response.status()).toBe(200);if(delivered.renderSpecification?.blocks[0].targetOrientation){if(pageMode==='TARGET')delivered.renderSpecification.blocks[0].targetOrientation='VERTICAL';if(pageMode==='SOURCE')delivered.blocks[0].geometry.orientation='HORIZONTAL';if(pageMode==='SPECIFICATION')delete delivered.renderSpecification;}reads.push({mode:pageMode,revision:actual.resultRevision});await route.fulfill({response,json:delivered});});
    const trace=await observeManualEditAck(page,{loseFirstBody:()=>loseBody});await direction.selectOption('HORIZONTAL');await activate(row.getByRole('button',{name:'수정 반영',exact:true}),touch);await expect(page.getByRole('alert')).toContainText('TRANSPORT_UNCONFIRMED');await expect(note).toBeVisible();expect(trace.edits).toHaveLength(1);const first=trace.edits[0],committed=(await currentResults(environment))[0],facts=await manualEditAckFacts(environment,first.command);expect(first.command.operation.payload.patch).toEqual({targetOrientation:'HORIZONTAL'});expect(committed.edit_data.blocks).toEqual(baseline.edit_data.blocks);expect(committed.edit_data.renderSpecification!.blocks[0]).toMatchObject({targetOrientation:'HORIZONTAL',rendererVersion:'pango-overflow-v2'});expect(committed.cleaned_asset_id).toBe(baseline.cleaned_asset_id);expect(facts.history).toHaveLength(1);
    loseBody=false;await activate(page.getByRole('button',{name:'같은 요청 다시 확인',exact:true}),touch);await expect.poll(()=>trace.edits.length).toBe(2);expect(trace.edits[1].body).toBe(first.body);expect(trace.edits[1].reply.disposition).toBe('EXISTING');await expect(note).toBeVisible();await expect(direction).toHaveValue('HORIZONTAL');
    for(const mode of ['SOURCE','SPECIFICATION'] as const){pageMode=mode;const readCount=reads.length;await page.clock.fastForward(5000);await expect.poll(()=>reads.length).toBeGreaterThan(readCount);expect(reads.at(-1)?.mode).toBe(mode);expect(reads.at(-1)?.revision).toBe(committed.result_revision);await expect(note).toBeVisible();await expect(direction).toHaveValue('HORIZONTAL');expect((await currentResults(environment))[0]).toEqual(committed);expect(trace.edits).toHaveLength(2);expect(await manualEditAckFacts(environment,first.command)).toEqual(facts);}
    pageMode='GOOD';await page.clock.fastForward(5000);await expect(note).toHaveCount(0);await expect(direction).toHaveValue('HORIZONTAL');await expect(row.getByText('사용자 확정',{exact:true})).toBeVisible();expect((await currentResults(environment))[0]).toEqual(committed);expect(await manualEditAckFacts(environment,first.command)).toEqual(facts);expect(trace.edits).toHaveLength(2);const after=await exitAckOriginalFacts(environment);for(const key of ['account','requests','executions','reservations','costs','settlements'] as const)expect(after[key]).toEqual(processing[key]);expect(environment.local.provider.calls).toHaveLength(2);await page.clock.resume();paused=false;await healthy(page,environment,jsErrors);await writeFile(artifact(info,'target-orientation-ack-evidence.json'),JSON.stringify({mode:'SYNTHETIC',realModelCalls:0,targetOnlyPatch:true,sourcePreserved:true,confirmedValuesPreserved:true,lostAckSameBodyRetry:true,dispositions:trace.edits.map(entry=>entry.reply.disposition),mismatchedReads:['TARGET','SOURCE','SPECIFICATION'],historyCount:1,automaticRetryPosts:0},null,2));
  }finally{if(paused)await page.clock.resume();}
});
